// src/roles/roles.guard.ts:10-22 RolesGuard.canActivate
  canActivate(context: ExecutionContext): boolean {
    const roles = this.reflector.getAllAndOverride<
      (number | string)[] | undefined
    >('roles', [context.getClass(), context.getHandler()]);
    if (!roles?.length) {
      return true;
    }
    const request = context
      .switchToHttp()
      .getRequest<RequestWithUser<JwtPayloadType | undefined>>();

    return roles.map(String).includes(String(request.user?.id));
  }

