export function pluralKebab(name: string): string {
  const lower = name.replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase();
  if (lower.endsWith('y')) return lower.slice(0, -1) + 'ies';
  if (lower.endsWith('s') || lower.endsWith('x') || lower.endsWith('z'))
    return lower + 'es';
  return lower + 's';
}

